/* =====================================================================
   CHAPTER 5 — 뉴욕에 가 본 적이 있어요? (travel experiences)
   Patterns: -은/-ㄴ 적이 있다/없다, -아서/-어서/-여서 그런지
   ===================================================================== */

Object.assign(CONTENT.skills, {
  jk:   { name: "-은/-ㄴ 적이 있다/없다 · form", rule: "Stem + -은 after a consonant, -ㄴ after a vowel: 먹은 적이 있어요, 본 적이 있어요. Not -는 and not -을: the experience is already behind you." },
  jku:  { name: "-은/-ㄴ 적이 있다/없다 · experience", rule: "It says whether something has ever happened to you. 한 번도 and 전혀 go with 없다. 가 본 적이 있어요 means the same as 가 봤어요." },
  gr:   { name: "-아서/-어서/-여서 그런지 · form", rule: "Take the -아서/-어서 form and add 그런지: 가서 그런지, 먹어서 그런지, 해서 그런지. Nouns take 이라서 after a consonant and 라서 after a vowel." },
  gru:  { name: "-아서/-어서/-여서 그런지 · a guessed reason", rule: "‘Perhaps because …’: you are guessing at the cause, and what follows has to be something that cause could explain." },
  eu:   { name: "으 drop (크다, 바쁘다, 쓰다)", rule: "Before -아/-어 the 으 disappears: 크다 → 커서, 바쁘다 → 바빠서, 쓰다 → 써서. Before -ㄴ nothing happens: 쓴." },
  voc5: { name: "Chapter 5 words · kinds of trip and why they were good", rule: "국내 is inside the country, 해외 abroad. 배낭여행 is backpacking, 패키지여행 a package tour, 신혼여행 a honeymoon, 도보 여행 a trip on foot." },
  col5: { name: "What makes a place good", rule: "물가가 저렴하다, 공기가 깨끗하다, 야경이 멋지다, 자연 경관이 아름답다, 전통문화를 느끼다; 문제가 생기다, 문제를 해결하다." },
});
CONTENT.skills.lst.rule = "ㄹ stems never take 으: 살면서, 만들면서. With -ㄹ까 the two ㄹ merge: 살까. Before -ㄴ the ㄹ drops: 산 적이 있어요, 만든 적이 있어요.";
CONTENT.skills.bir.rule = "Before a vowel ending ㅂ turns into 우 (오 in 돕다 + -아): 도울 줄 알아요, 도와, 더워, 주운 적이 있어요, 가까워서. Before -고 and -자 nothing changes. 입다 and 잡다 are regular.";
CONTENT.skills.rir.rule = "Before -아/-어, 르 loses its ㅡ and the ㄹ doubles: 불러라, 골라라, 빨라서, 몰라서. Before other endings nothing changes: 부르자, 부른 적이 있어요.";

